const input = $input.first().json;
const task = input.task || 'general_summary';
const model = input.model || 'qwen2.5:3b';
const finding = input.finding || input.digest || {};

function safeString(obj, max=2000) {
  const s = JSON.stringify(obj, null, 2);
  return s.length > max ? s.slice(0, max) + '...[truncated]' : s;
}

let system = 'You are a compliance operations assistant. Draft clear, factual text only.';
let user = safeString(finding);

if (task === 'remediation_summary') {
  system = 'You are a compliance remediation writer. Write concise, factual ticket text. Do not decide ownership, severity, closure, or risk acceptance.';
  user = `Draft a remediation summary for this finding:
${safeString(finding)}

Return sections: Issue, Likely cause, Recommended remediation, Auditor note`;
}
if (task === 'weekly_governance_digest') {
  system = 'You are a compliance operations analyst. Summarize operational metrics for leadership. Do not invent facts.';
  user = `Summarize this digest:
${safeString(finding)}

Return: Executive summary, Top risks, Recommended follow-ups`;
}

return [{
  json: { model, messages: [{role:'system',content:system},{role:'user',content:user}], stream: false, options: { temperature: 0.2, num_predict: input.maxTokens || 500 } }
}];

const resp = $input.first().json;
const text = resp?.message?.content || resp?.response || '';
return [{ json: { aiText: text.trim(), aiStatus: text.trim() ? 'ok' : 'empty' } }];

return [{
  json: {
    aiText: $input.first().json.aiText,
    aiStatus: $input.first().json.aiStatus,
    findingKey: $input.all()[0]?.json?.findingKey || null
  }
}];
